head.script:
scwin.screenId = "jldfil16601";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await $c.win.openPopup('/jldfil16601/jldfil16601_layer_layer1.xml', {id:'jldfil16601_layer_layer1', type:'pageFramePopup'}, {});
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16601.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16601.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_pageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearch();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16601.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_applList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_applList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_applList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_applList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.fnWrite === 'function') { await scwin.fnWrite(r["comSchdlId"], r["comSchdlTpCd"], r["regYn"], r["applObjLmtYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fnWrite (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fnWrite'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_applList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        target: "dlt_applList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16601.tx_fnSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnWrite = async function () {
    const sbmOptions = {
        id: "tx_fnWrite",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnWriteReq",
        target: "dlt_applList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16601.tx_fnWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnApplComCntChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnApplComCntChk = async function () {
    const sbmOptions = {
        id: "tx_fnApplComCntChk",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnApplComCntChkReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16601.tx_fnApplComCntChk" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplList");
    $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_comSchdlId ipt_comSchdlTpCd regYn applObjLmtYn
 * @returns
 * @hidden N
*/
scwin.fnWrite = async function (ipt_comSchdlId, ipt_comSchdlTpCd, regYn, applObjLmtYn) {
    /* sdd-asis-lifecycle:begin fnWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (regYn === 'Y') {
        await $c.win.alert('이미 신청되었습니다.\n신청내역에서 확인하세요.');
        return;
    }
    if (applObjLmtYn === 'Y') {
        const bl = await scwin.fnApplComCntChk(ipt_comSchdlId);
        if (bl === 'false') {
            await $c.win.alert('신청가능한 법인수를 초과하였습니다.\n다음에 신청해주세요.');
            return;
        }
    }
    $c.util.getComponent('ipt_comSchdlId').setValue(ipt_comSchdlId);
    $c.util.getComponent('ipt_comSchdlTpCd').setValue(ipt_comSchdlTpCd);
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplForm");
    $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnWrite();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.layer_popup
 * @author Inswave
 * @date 2026. 09. 29
 * @param el
 * @returns
 * @hidden N
*/
scwin.layer_popup = function (el) {
    /* sdd-asis-lifecycle:begin layer_popup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const $el = $(el);
    const isDim = $el.prev().hasClass('dimBg');
    isDim ? $('.dim-layer').fadeIn() : $el.fadeIn();
    let $elWidth = ~~($el.outerWidth()), $elHeight = ~~($el.outerHeight()), docWidth = $(document).width(), docHeight = $(document).height();
    if ($elHeight < docHeight || $elWidth < docWidth) {
        $elHeight = 900;
        $el.css({ marginTop: -$elHeight / 2, marginLeft: -$elWidth / 2 });
    } else {
        $el.css({ top: 0, left: 0 });
    }
    $el.find('a.btn-layerClose').click(function() {
            isDim ? $('.dim-layer').fadeOut() : $el.fadeOut();
            return false;
    });
    $('.layer .dimBg').click(function() {
            $('.dim-layer').fadeOut();
            return false;
    });
    /* sdd-asis-lifecycle:end */
};


// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fnSearch, tx_fnWrite) — 어느 것이 «열자마자» 인지 정할 근거가 없다

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.fnApplComCntChk_done
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnApplComCntChk_done = function (data) {
    /* sdd-asis-lifecycle:begin fnApplComCntChk_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    bl = scwin.result.returnVal;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.fnApplComCntChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnApplComCntChk = async function () {
    const r = await scwin.tx_fnApplComCntChk();
    try {
        scwin.fnApplComCntChk_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil16601.fnApplComCntChk' });
    }
    return r;
};


/**
 * @event
 * @name scwin.krxpage_pagenavigator_43_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_43_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.fnSearch(); };
